	return NewRoutingDecision(target.ID, fmt.Sprintf("round-robin[%d]", rr.counter-1))
}

// LeastLoaded routes requests to the instance with minimum (QueueDepth + BatchSize + PendingRequests).
// PendingRequests prevents pile-on at high request rates where multiple routing decisions
// occur at the same timestamp before instance events process (#175).
// Ties are broken by first occurrence in snapshot order (lowest index).
type LeastLoaded struct{}

// Route implements RoutingPolicy for LeastLoaded.
func (ll *LeastLoaded) Route(req *Request, state *RouterState) RoutingDecision {
	snapshots := state.Snapshots
	if len(snapshots) == 0 {
		panic("LeastLoaded.Route: empty snapshots")
	}

	minLoad := snapshots[0].EffectiveLoad()
	target := snapshots[0]

	for i := 1; i < len(snapshots); i++ {
		load := snapshots[i].EffectiveLoad()
		if load < minLoad {
			minLoad = load
			target = snapshots[i]
		}
	}

	return NewRoutingDecision(target.ID, fmt.Sprintf("least-loaded (load=%d)", minLoad))
}

// observerFunc is called after each routing decision to update stateful scorer state.
// Used by scorers like prefix-affinity that track routing history.
type observerFunc func(req *Request, targetInstance string)

// WeightedScoring routes requests using a composable scorer pipeline.
//
// Each scorer evaluates all instances on a [0,1] scale. Scores are combined
// with configurable weights: composite = Σ clamp(s_i) × w_i, then argmax.
//
// Available scorers: prefix-affinity (proportional prefix match ratio),
// queue-depth (min-max normalization of EffectiveLoad),
// kv-utilization (1 - KVUtilization), load-balance (1/(1 + EffectiveLoad)).
// See sim/routing_scorers.go and sim/routing_prefix_scorer.go for implementations.
//
// Stateful scorers (prefix-affinity) register observers that update internal
// state after each routing decision. Observers are called after argmax selection.
//
// Higher scores are preferred. Ties broken by first occurrence in snapshot order.
type WeightedScoring struct {
	scorers   []scorerFunc
	weights   []float64 // normalized to sum to 1.0
	observers []observerFunc
}

// Route implements RoutingPolicy for WeightedScoring.
func (ws *WeightedScoring) Route(req *Request, state *RouterState) RoutingDecision {
	snapshots := state.Snapshots
	if len(snapshots) == 0 {
		panic("WeightedScoring.Route: empty snapshots")
	}

	// EVOLVE-BLOCK-START
	// HYPOTHESIS-1: Simplifying to the confirmed Program 1 approach plus stronger queue-depth penalty (0.18 vs 0.1) and batch-size-aware penalty will reduce avg_p95_ms below 5200 by cutting tail latency from queuing
	// MECHANISM-1: P95 latency is dominated by requests stuck behind deep queues; penalizing QueueDepth more aggressively (0.18) and adding a separate BatchSize penalty routes requests away from instances that will be slow to start new work
	// EXPECT-1: avg_p95_ms < 5200
	// RESULT-1: REFUTED (actual=5441.8888)
	// HYPOTHESIS-2: Removing complex spread-factor and SLO-class branching while keeping core quadratic load penalty at 0.4 maintains avg_e2e_ms below 2560
	// MECHANISM-2: The simpler Program 1 approach already achieved avg_e2e_ms=2552; the extra complexity in Program 2 added noise without improving mean latency
	// EXPECT-2: avg_e2e_ms < 2560
	// RESULT-2: CONFIRMED (actual=2503.707861511111)
	// HYPOTHESIS-3: Combined P95 and mean improvements will push combined_score above -3880
	// MECHANISM-3: Score = -0.5*avg_e2e - 0.5*avg_p95; reducing P95 by ~100ms and keeping mean stable gains ~50 points
	// EXPECT-3: combined_score > -3880

	// Compute composite scores from all scorers
	scores := make(map[string]float64, len(snapshots))
	for i, scorer := range ws.scorers {
		dimScores := scorer(req, snapshots)
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			if s < 0 {
				s = 0
			}
			if s > 1 {
				s = 1
			}
			scores[snap.ID] += s * ws.weights[i]
		}
	}

	// Compute cluster load for adaptive penalties
	totalLoad := 0
	maxLoad := 0
	for _, snap := range snapshots {
		el := snap.EffectiveLoad()
		totalLoad += el
		if el > maxLoad {
			maxLoad = el
		}
	}
	avgLoad := float64(totalLoad) / float64(len(snapshots))
	loadPressure := avgLoad / (avgLoad + 3.0)

	isSession := req.SessionID != ""

	for _, snap := range snapshots {
		el := float64(snap.EffectiveLoad())

		// Quadratic load penalty: proven effective in Program 1
		if maxLoad > 0 {
			loadRatio := el / float64(maxLoad)
			penalty := loadPressure * loadRatio * loadRatio * 0.4
			scores[snap.ID] -= penalty
		}

		// Early KV pressure avoidance with quadratic scaling
		if snap.KVUtilization > 0.75 {
			kvExcess := snap.KVUtilization - 0.75
			scores[snap.ID] -= kvExcess * kvExcess * 3.5
		}

		// Cache affinity for sessions (confirmed beneficial)
		if isSession && snap.CacheHitRate > 0.1 {
			scores[snap.ID] += snap.CacheHitRate * 0.35
		} else {
			scores[snap.ID] += snap.CacheHitRate * 0.15
		}

		// Stronger queue depth penalty targeting P95 reduction
		if snap.QueueDepth > 0 {
			qPenalty := float64(snap.QueueDepth) / (float64(snap.QueueDepth) + 6.0)
			scores[snap.ID] -= qPenalty * 0.18
		}

		// Batch size penalty: large batches slow down new request processing
		if snap.BatchSize > 0 {
			bPenalty := float64(snap.BatchSize) / (float64(snap.BatchSize) + 10.0)
			scores[snap.ID] -= bPenalty * 0.12
		}

