		if len(req.InputTokens) > 400 && snap.FreeKVBlocks > 0 {
			freeNorm := float64(snap.FreeKVBlocks) / (float64(snap.FreeKVBlocks) + 80.0)
			scores[snap.ID] += freeNorm * 0.1
		}
